import { readFile, writeFile } from 'node:fs/promises';
const profile = await readFile(new URL('../personal-ocean/prompts/mingze.txt', import.meta.url), 'utf8');
await writeFile(new URL('./functions/personal-chat/profile.ts', import.meta.url),
  '// Generated by supabase/sync-prompt.mjs. Keep the website profile as the source of truth.\n' +
  `export const PROFILE = ${JSON.stringify(profile)};\n`);
console.log('Synced personal website profile to the deployable Edge Function module.');
